<div class="interactive-wrapper"><div class="card shadow-sm border-0 mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#eef2ff"><i class="fas fa-bread-slice text-primary"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Sourdough Bakers Calc</h5><p class="text-muted small mb-0">Calculate baker's percentages and hydration</p></div></div><button class="btn btn-sm rounded-pill px-3" id="btn-reset" style="background:#f1f5f9;font-weight:600"><i class="fas fa-undo me-1"></i>Reset</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="row g-3"><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Flour (g)</label><input type="number" id="in-flour" class="form-control form-control-lg" value="500" step="1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Water (g)</label><input type="number" id="in-water" class="form-control form-control-lg" value="350" step="1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Salt (g)</label><input type="number" id="in-salt" class="form-control form-control-lg" value="10" step="0.1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Starter (g)</label><input type="number" id="in-starter" class="form-control form-control-lg" value="100" step="1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Hydration %</label><input type="number" id="in-hydration" class="form-control form-control-lg" value="" placeholder="auto" step="0.1"></div><div class="col-md-4"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">Flour Type</label><select id="in-type" class="form-select form-select-lg"><option value="bread">Bread Flour</option><option value="ap">All Purpose</option><option value="whole">Whole Wheat</option><option value="rye">Rye</option></select></div></div><div class="mt-4 text-center"><button class="btn btn-primary btn-lg rounded-pill px-5 shadow-sm" id="btn-calc" style="min-width:260px;max-width:100%"><i class="fas fa-calculator me-2"></i>Calculate</button></div><div class="mt-3 p-3 rounded-4 border" style="background:#f8fafc"><p class="mb-0 small text-muted"><i class="fas fa-info-circle text-primary me-2"></i><b>Baker's %:</b> All ingredients as percentage of total flour weight</p></div></div></div><div id="res" class="card shadow-sm border-0 d-none mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#ecfdf5"><i class="fas fa-check-circle text-success"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Result</h5></div></div><button class="btn btn-success btn-sm rounded-pill px-4 shadow-sm" id="btn-copy"><i class="fas fa-copy me-1"></i>Copy</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="p-4 rounded-4 bg-light border text-center mb-3"><div class="small fw-bold text-uppercase text-muted mb-1">RESULT</div><div class="display-4 fw-bold text-dark" id="out-main">—</div><div class="small text-muted fw-bold" id="out-unit"></div></div><div id="out-detail" class="row g-3 mb-3"></div><div class="p-4 rounded-4 bg-light border"><h6 class="fw-bold mb-2 small text-uppercase text-muted"><i class="fas fa-lightbulb text-warning me-2"></i>Insights</h6><div id="out-ins" class="small"></div></div></div></div></div><style>.form-control-lg,.form-select-lg{border:1.5px solid #e2e8f0;border-radius:12px;font-size:1.05rem;padding:.75rem 1rem}.form-control:focus,.form-select:focus{border-color:#4f46e5;box-shadow:0 0 0 4px rgba(79,70,229,.1)}</style><script>document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var flour=parseFloat(document.getElementById("in-flour").value)||0,water=parseFloat(document.getElementById("in-water").value)||0,salt=parseFloat(document.getElementById("in-salt").value)||0,starter=parseFloat(document.getElementById("in-starter").value)||0;if(flour===0)return;var starterFlour=starter*0.5,starterWater=starter*0.5;var totalFlour=flour+starterFlour;var totalWater=water+starterWater;var hydration=(totalWater/totalFlour)*100;var saltPct=(salt/totalFlour)*100;var starterPct=(starter/flour)*100;var total=flour+water+salt+starter;document.getElementById("out-main").textContent=hydration.toFixed(1)+"%";document.getElementById("out-unit").textContent="Total Hydration";document.getElementById("out-detail").innerHTML='<div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Total Dough</div><div class="h5 fw-bold mb-0 text-primary">'+total+' g</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Salt %</div><div class="h5 fw-bold mb-0 text-info">'+saltPct.toFixed(1)+'%</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Starter %</div><div class="h5 fw-bold mb-0 text-warning">'+starterPct.toFixed(1)+'%</div></div></div><div class="col-3"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Total Flour</div><div class="h5 fw-bold mb-0 text-success">'+totalFlour.toFixed(0)+' g</div></div></div>';var ins=["Hydration: <b>"+hydration.toFixed(1)+"%</b> (includes starter water)"];if(hydration>80)ins.push("High hydration — expect an open crumb but sticky dough");else if(hydration<65)ins.push("Low hydration — denser crumb, easier to handle");if(saltPct<1.5)ins.push("⚠ Salt is low — consider 1.8-2.2% for flavor");document.getElementById("out-ins").innerHTML='<ul class="list-unstyled mb-0">'+ins.map(function(x){return'<li class="mb-2"><i class="fas fa-check-circle text-success me-2"></i>'+x+"</li>";}).join("")+"</ul>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-flour").value=500;document.getElementById("in-water").value=350;document.getElementById("in-salt").value=10;document.getElementById("in-starter").value=100;document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText("Hydration: "+document.getElementById("out-main").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\"fas fa-copy me-1\"></i>Copy";},2e3);});});</script><?php /**PATH D:\Xamp\htdocs\ToolsHub\resources\views\tools\interactive\sourdough-bakers-calc.blade.php ENDPATH**/ ?>